import json
import pandas as pd

sources = {
    'source_a': '/data/source_a/users.json',
    'source_b': '/data/source_b/users.csv',
    'source_c': '/data/source_c/users.parquet',
}
priority = ['source_a', 'source_b', 'source_c']
fields = ['user_id', 'name', 'email', 'created_date', 'status']
aliases = {
    'user_id': ['user_id', 'id', 'userId'],
    'name': ['full_name', 'name', 'userName'],
    'email': ['email', 'email_address'],
    'created_date': ['registration_date', 'created_at', 'joined'],
    'status': ['status', 'is_active'],
}

def read_source(src, path):
    if src == 'source_a':
        with open(path, encoding='utf-8') as f:
            obj = json.load(f)
        if isinstance(obj, dict):
            obj = obj.get('users', obj.get('data', obj.get('records', [obj])))
        return pd.DataFrame(obj)
    if src == 'source_b':
        return pd.read_csv(path)
    return pd.read_parquet(path)

def missing(v):
    if v is None:
        return True
    try:
        return bool(pd.isna(v))
    except (TypeError, ValueError):
        return False

def norm(v, field):
    if missing(v):
        return None
    if field == 'user_id':
        return int(v)
    if field == 'created_date':
        d = pd.to_datetime(str(v).strip(), errors='coerce')
        return str(v).strip() if pd.isna(d) else d.strftime('%Y-%m-%d')
    if field == 'status' and isinstance(v, bool):
        return 'true' if v else 'false'
    return str(v).strip()

def normalize(df):
    result = []
    for _, row in df.iterrows():
        rec = {}
        for target, names in aliases.items():
            rec[target] = None
            for name in names:
                if name in df.columns:
                    value = norm(row[name], target)
                    if value is not None:
                        rec[target] = value
                        break
        if rec['user_id'] is not None:
            result.append(rec)
    return result

by_source = {}
for src, path in sources.items():
    grouped = {}
    for rec in normalize(read_source(src, path)):
        uid = rec['user_id']
        if uid not in grouped:
            grouped[uid] = rec
        else:
            for field in fields[1:]:
                if grouped[uid][field] is None and rec[field] is not None:
                    grouped[uid][field] = rec[field]
    by_source[src] = grouped

conflicts = []
merged = []
for uid in sorted(set().union(*(set(x) for x in by_source.values()))):
    row = {'user_id': uid}
    for field in fields[1:]:
        vals = {src: by_source[src][uid][field] for src in priority if uid in by_source[src] and by_source[src][uid][field] is not None}
        selected = next((vals[src] for src in priority if src in vals), None)
        row[field] = selected
        if len(set(vals.values())) > 1:
            conflicts.append({'user_id': uid, 'field': field, 'values': vals, 'selected': selected})
    merged.append(row)

out = pd.DataFrame(merged, columns=fields)
out['user_id'] = out['user_id'].astype('int64')
out.to_parquet('/app/merged_users.parquet', index=False)
with open('/app/conflicts.json', 'w', encoding='utf-8') as f:
    json.dump({'total_conflicts': len(conflicts), 'conflicts': conflicts}, f, indent=2)
print('merged rows:', len(out))
print('conflicts:', len(conflicts))
print(out.to_string(index=False))
